grammar.syntax:
constexpr int MAX = 100;
auto x = 42;
void *ptr = nullptr;

grammar.example:
#include <stdio.h>
#include <stdint.h>

int main(void) {
    constexpr int32_t count = 10;
    void *p = nullptr;
    printf("count: %d, p is null: %s\n", count, p == nullptr ? "true" : "false");
    return 0;
}

grammar.syntax:
if (cond) { ... } else { ... }
switch (val) { case 1: ... break; default: ... }
for (int i = 0; i < n; i++) { ... }

grammar.example:
#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 5; i++) {
        if (i % 2 == 0) {
            printf("%d is even\n", i);
        } else {
            printf("%d is odd\n", i);
        }
    }
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void) {
    int x = 10, y = 20;
    swap(&x, &y);
    printf("x=%d, y=%d\n", x, y);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *nums = malloc(3 * sizeof(int));
    if (nums == NULL) return 1;
    nums[0] = 10; nums[1] = 20; nums[2] = 30;
    printf("nums[1] = %d\n", nums[1]);
    free(nums);
    return 0;
}

#include <stdio.h>

typedef struct {
    int id;
    char name[32];
} Student;

int main(void) {
    Student s = { .id = 1, .name = "Neo" };
    printf("Student #%d: %s\n", s.id, s.name);
    return 0;
}

#include <stdio.h>
#define SQUARE(x) ((x) * (x))

int main(void) {
    printf("5 squared: %d\n", SQUARE(5));
    return 0;
}
